using System;using System.Diagnostics;using System.IO;using System.Drawing;using System.Drawing.Imaging;
class RenderWorker{[STAThread]static int Main(string[] args){try{if(args.Length!=3)return 2;int size=Math.Clamp(int.Parse(args[2]),32,512);string ext=Path.GetExtension(args[0]);if(LargeStl.IsLarge(args[0]))Process.GetCurrentProcess().PriorityClass=ProcessPriorityClass.BelowNormal;using(var image=ext.Equals(".3mf",StringComparison.OrdinalIgnoreCase)?Thumbnail.RenderOrEmbedded(args[0]):MeshFormats.Render(args[0]))using(var scaled=new Bitmap(size,size,PixelFormat.Format24bppRgb)){using(var g=Graphics.FromImage(scaled)){g.Clear(Color.FromArgb(225,225,223));g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;g.DrawImage(image,0,0,size,size);}scaled.Save(args[1],ImageFormat.Bmp);}return 0;}catch{return 1;}}}